// GitHub → Summary tab (all-repos analytics), AS GRAPH SOURCE (#3650, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the github lib/hook surface + planner board via the github
// graph-platform, and the sibling views as @/components/* graph records). Behaviour runs here.
// The GitHub summary dashboard — the cross-repo analytics view (#1644).
//
// Presentation/composition only: the data + derivations live in `useGithubSummary`,
// the per-card UI in `summary/*`, and the React-free shaping in `lib/githubSummary.ts`.

import { useAppStore } from "@/store";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Grid } from "@/shared/ui/layout/Grid";
import { Box } from "@/shared/ui/layout/Box";
import { StatTile } from "@/shared/ui/data/StatTile";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { useGithubSummary } from "@/features/github/useGithubSummary";
import { ActivityHeatmap } from "@/components/github-activity-heatmap";
import { LanguageMix } from "@/components/github-language-mix";
import { ContributorsCard } from "@/components/github-contributors";
import { CrossRepoActivity } from "@/components/github-cross-repo-activity";
import { OpenPRsAllRepos } from "@/components/github-open-prs";
import { ReposGrid } from "@/components/github-repos-grid";
import { CIHealthCard } from "@/components/github-ci-health";

// Re-export the shared page-mode strip from its previous home so existing
// `@/features/github/GitHubSummary` importers keep working.
export { GitHubPageModeStrip } from "@/components/github-page-mode-strip";

export function GitHubSummary() {
  const setGithubPageMode = useAppStore(s => s.setGithubPageMode);
  const {
    loading, githubRepos,
    heatmap, totalMerged, crossRepoEvts, openPRs,
    langTotals, langRepoCount, contributors, ciMatrix, repoGridData,
    kpiOpenPRs, kpiContribs, kpiCIPassing,
  } = useGithubSummary();
  const { heatmapCells, rawCounts, rawDates, totalContribs } = heatmap;

  return (
    <Box as="section" pad={[20, 24]} bg="var(--bg-canvas)" style={{ flex: 1, overflow: "auto", minWidth: 0}}>
      <Box style={{ maxWidth: 1280, margin: "0 auto" }}>
        <Row align="start" gap={14} style={{ marginBottom: 14 }}>
          <Box style={{ flex: 1 }}>
            <Text as="h2" mono size={20} weight={600} style={{ margin: 0 }}>Across all repositories</Text>
            <Text as="div" tone="muted" size="md" style={{ marginTop: 4 }}>
              {githubRepos.length} repo{githubRepos.length !== 1 ? "s" : ""} · 28-week view
            </Text>
          </Box>
          <Button onClick={() => setGithubPageMode("repos")}>browse repositories →</Button>
        </Row>

        <Grid cols={6} gap={8} style={{ marginBottom: 14 }}>
          {([
            // The repositories count is known immediately; every other tile shimmers until the
            // GitHub fetch resolves (#2244) — so the KPI row keeps its shape rather than flashing "…".
            ["repositories", String(githubRepos.length),               "all connected",                 "fg",      false  ],
            ["open PRs",     String(kpiOpenPRs),       `${openPRs.filter(p => !p.draft).length} ready to review`, "accent",  loading],
            ["contributions · 28w", String(totalContribs), "commits · PRs · issues",      "success", loading],
            ["CI passing",   kpiCIPassing != null ? `${kpiCIPassing}%` : "—", "latest run per repo", "info",    loading],
            ["contributors", String(kpiContribs),      "all repos",                     "muted",   loading],
            ["merged PRs",       String(totalMerged),   "last ~90 days via events",      "muted",   loading],
          ] as const).map(([k, v, sub, tone, tileLoading]) => (
            <StatTile
              key={k}
              k={k}
              v={v}
              sub={sub}
              tone={tone === "accent" ? "accent" : tone === "success" ? "success" : undefined}
              vStyle={tone === "info" ? { color: "var(--info)" } : undefined}
              loading={tileLoading}
            />
          ))}
        </Grid>

        <Grid cols="1.7fr 1fr" gap={14}>
          <Stack gap={14} style={{ minWidth: 0 }}>
            <ReposGrid repos={repoGridData} loading={loading} />
            <CrossRepoActivity events={crossRepoEvts} loading={loading} />
            <OpenPRsAllRepos prs={openPRs} loading={loading} />
          </Stack>
          <Stack gap={14} style={{ minWidth: 0 }}>
            <ActivityHeatmap cells={heatmapCells} rawCounts={rawCounts} rawDates={rawDates} totalContribs={totalContribs} totalMerged={totalMerged} loading={loading} />
            <CIHealthCard matrix={ciMatrix} loading={loading} />
            <ContributorsCard contributors={contributors} loading={loading} />
            <LanguageMix langTotals={langTotals} repoCount={langRepoCount} totalRepos={githubRepos.length} loading={loading} />
          </Stack>
        </Grid>
      </Box>
    </Box>
  );
}
